-- ES/DE/FR translations for France's and Poland's lifecycle cards
-- in the new v2 schema.

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text) SELECT dlc.id, 'es', 'Intercambio de estados del ciclo de vida', 'Toda factura debe llevar actualizaciones de estado a lo largo de su vida — esto es lo que permite a la DGFiP prellenar las declaraciones de IVA casi en tiempo real.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'France';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text) SELECT dlc.id, 'de', 'Austausch von Lebenszyklusstatus', 'Jede Rechnung muss während ihres gesamten Lebenszyklus Statusaktualisierungen tragen — dies ermöglicht es der DGFiP, Umsatzsteuererklärungen nahezu in Echtzeit vorauszufüllen.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'France';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text) SELECT dlc.id, 'fr', 'Échange des statuts de cycle de vie', 'Chaque facture doit porter des mises à jour de statut tout au long de sa vie — c''est ce qui permet à la DGFiP de pré-remplir les déclarations de TVA quasiment en temps réel.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'France';
